pre.code:
:root {
  --theme-name: "My reading theme";
  --theme-name-en: "My reading theme";
  --theme-description: "Serif text for long-form reading";
  --theme-base: craft;
  --accent: hsl(212, 70%, 45%);
}
.page { font-family: Georgia, serif; font-size: 17px; line-height: 1.8; max-width: 680px; }
h1 { font-size: 1.6em; font-weight: 700; margin-top: 40px; }
a { color: var(--accent); text-decoration: underline; }
blockquote { border-left: 3px solid var(--accent); font-style: italic; }
hr { border-top: 1px solid #d0d0d0; }
